-- 132_geography_names.sql — GEO_HARDCODE_V1: ГЕОГРАФИЯ ЗАШИТА В ПРОГРАММУ.
--
-- Владелец (2026-09-15): «easymed should have hardcoded list of the
-- specialties and the geography… its not fetched from the medcore, it should
-- be only cloned to the easymed». Страна / регион / район — выпадающие списки;
-- адрес и махалля — свободный текст (списка махаллей не нужно).
--
-- Источник — «Справочники EasyMed (бланк).xlsx» (Desktop/easymed reference):
-- 7 стран, 14 регионов Узбекистана, 206 районов и городов областного
-- подчинения — с названиями на ru / uz / en и кодами. Миграция 030 заводила
-- регионы и 12 районов Ташкента: они дополняются названиями и кодами, а не
-- пересоздаются; остальные районы вставляются, если такого имени в регионе
-- ещё нет. ТОЛЬКО ADD COLUMN / UPDATE / INSERT.
ALTER TABLE countries ADD COLUMN name_uz TEXT;
ALTER TABLE countries ADD COLUMN name_en TEXT;
ALTER TABLE regions   ADD COLUMN code    TEXT;
ALTER TABLE regions   ADD COLUMN name_uz TEXT;
ALTER TABLE regions   ADD COLUMN name_en TEXT;
ALTER TABLE districts ADD COLUMN code    TEXT;
ALTER TABLE districts ADD COLUMN name_uz TEXT;
ALTER TABLE districts ADD COLUMN name_en TEXT;
ALTER TABLE districts ADD COLUMN kind    TEXT;

